#!/bin/bash
# Lint sources using clang-tidy or other tools if available.
# This script is a placeholder/basic implementation.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$SCRIPT_DIR/.."
BUILD_DIR="$PROJECT_ROOT/build"

echo "Linting C++ sources..."

# Check if compile_commands.json exists (generated by cmake -DCMAKE_EXPORT_COMPILE_COMMANDS=ON)
if [ ! -f "$BUILD_DIR/compile_commands.json" ]; then
    echo "Warning: compile_commands.json not found in $BUILD_DIR. Attempting to generate..."
    cmake -S "$PROJECT_ROOT" -B "$BUILD_DIR" -DCMAKE_EXPORT_COMPILE_COMMANDS=ON
fi

if [ -f "$BUILD_DIR/compile_commands.json" ]; then
    # Run clang-tidy on sources
    # Note: excluding 3rdparty if any
    find "$PROJECT_ROOT/src" "$PROJECT_ROOT/examples" \
        -name "*.cpp" | \
        xargs clang-tidy -p "$BUILD_DIR"
else
    echo "Error: Could not generate compile_commands.json. clang-tidy might fail."
fi

echo "Done."
